  nebula: { name: 'Nebula', to: 'amethyst' },
  'indigo-night': { name: 'Indigo Night', to: 'amethyst' },
  celestial: { name: 'Celestial', to: 'cobalt' },
  wisteria: { name: 'Wisteria', to: 'amethyst' },
  inferno: { name: 'Inferno', to: 'ember' },
  wildfire: { name: 'Wildfire', to: 'ember' },
  aurora: { name: 'Aurora', to: 'solar' },
  void: { name: 'Void', to: 'obsidian' },
  storm: { name: 'Storm', to: 'frost' },
  static: { name: 'Static', to: 'obsidian' },
  wraith: { name: 'Wraith', to: 'obsidian' },
  ashen: { name: 'Ashen', to: 'obsidian' },
  'olive-grove': { name: 'Olive Grove', to: 'solar' },
